import { performance } from 'node:perf_hooks'

export async function checkout(url) {
  const start = performance.now()
  const response = await fetch(`${url}/checkout`)
  const body = await response.json()
  const totalMs = performance.now() - start
  if (!response.ok) throw new Error(`checkout failed: ${response.status}`)
  return { body, totalMs }
}
import { createServer } from 'node:http'
import { performance } from 'node:perf_hooks'
import { pathToFileURL } from 'node:url'
import { quoteShipping } from './src/external.mjs'
import { buildOrder, createOrderLines } from './src/order.mjs'

export function createOrderServer() {
  const lines = createOrderLines()
  return createServer(async (request, response) => {
    if (request.method !== 'GET' || request.url !== '/checkout') {
      response.writeHead(404).end('not found')
      return
    }

    const externalStart = performance.now()
    const quotes = await quoteShipping(lines)
    const externalMs = performance.now() - externalStart

    const localStart = performance.now()
    const order = buildOrder(lines, quotes)
    const localMs = performance.now() - localStart

    response.writeHead(200, {
      'content-type': 'application/json',
      'server-timing': `external;dur=${externalMs.toFixed(3)}, local;dur=${localMs.toFixed(3)}`,
    })
    response.end(JSON.stringify({ ...order, phases: { externalMs, localMs } }))
  })
}

export function startOrderServer() {
  const server = createOrderServer()
  return new Promise((resolve, reject) => {
    server.once('error', reject)
    server.listen(0, '127.0.0.1', () => {
      const address = server.address()
      if (!address || typeof address === 'string') {
        reject(new Error('server did not expose a TCP address'))
        return
      }
      resolve({ server, url: `http://127.0.0.1:${address.port}` })
    })
  })
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const { url } = await startOrderServer()
  console.log(url)
}

export function createOrderLines(count = 2_000) {
  return Array.from({ length: count }, (_, index) => ({
    sku: `sku-${String(index % 700).padStart(4, '0')}`,
    weight: 0.5 + (index % 11) / 10,
    quantity: 1 + (index % 3),
  }))
}

export function buildOrder(lines, quotes) {
  const quoteBySku = new Map(quotes.map((quote) => [quote.sku, quote.quote]))
  let subtotal = 0
  const items = []

  for (const line of lines) {
    const quote = quoteBySku.get(line.sku)
    if (quote === undefined) throw new Error(`missing quote for ${line.sku}`)
    const total = quote * line.quantity
    subtotal += total
    items.push({ ...line, quote, total })
  }

  return { items, subtotal: Math.round(subtotal * 100) / 100 }
}
import { setTimeout as delay } from 'node:timers/promises'

export async function quoteShipping(items, delayMs = Number(process.env.EXTERNAL_DELAY_MS ?? 80)) {
  await delay(delayMs)
  return items.map((item) => ({
    sku: item.sku,
    quote: Math.round((item.weight * 1.75 + 4) * 100) / 100,
  }))
}

import { checkout } from './client.mjs'
import { startOrderServer } from './server.mjs'

const { server, url } = await startOrderServer()
try {
  const samples = []
  for (let index = 0; index < 3; index += 1) {
    const { body, totalMs } = await checkout(url)
    samples.push({
      totalMs: Number(totalMs.toFixed(3)),
      externalMs: Number(body.phases.externalMs.toFixed(3)),
      localMs: Number(body.phases.localMs.toFixed(3)),
      itemCount: body.items.length,
    })
  }
  console.log(JSON.stringify({ externalDelayMs: Number(process.env.EXTERNAL_DELAY_MS ?? 80), samples }, null, 2))
} finally {
  await new Promise((resolve) => server.close(resolve))
}
import assert from 'node:assert/strict'
import { test } from 'node:test'
import { buildOrder } from '../src/order.mjs'

test('checkout combines every production order line with its shipping quote', () => {
  const order = buildOrder(
    [
      { sku: 'a', weight: 1, quantity: 2 },
      { sku: 'b', weight: 2, quantity: 1 },
    ],
    [
      { sku: 'a', quote: 5 },
      { sku: 'b', quote: 7 },
    ],
  )
  assert.equal(order.items.length, 2)
  assert.equal(order.subtotal, 17)
  assert.deepEqual(
    order.items.map((item) => item.total),
    [10, 7],
  )
})

