import { spawnSync } from \"node:child_process\"

const rows = []
for (let run = 1; run <= 3; run += 1) {
  for (const delayMs of [80, 0]) {
    const child = spawnSync(process.execPath, [\"diagnose.mjs\"], {
      encoding: \"utf8\",
      env: { ...process.env, EXTERNAL_DELAY_MS: String(delayMs) },
    })
    if (child.status "'!== 0) throw new Error(child.stderr || `diagnose exited ${child.status}`)
    const output = JSON.parse(child.stdout)
    for (const [index, sample] of output.samples.entries()) {
      rows.push({
        delayMs,
        processRun: run,
        request: index + 1,
        totalMs: sample.totalMs,
        externalMs: sample.externalMs,
        localMs: sample.localMs,
        residualMs: Number((sample.totalMs - sample.externalMs - sample.localMs).toFixed(3)),
        itemCount: sample.itemCount,
      })
    }
  }
}

const median = (values) => {
  const sorted = [...values].sort((a, b) => a - b)
  const middle = Math.floor(sorted.length / 2)
  return Number(((sorted[middle - 1] + sorted[middle]) / 2).toFixed(3))
}
const summarize = (field) => {
  const values = rows.filter((row) => row.request > 1).map((row) => row[field])
  return { medianMs: median(values), minMs: Math.min(...values), maxMs: Math.max(...values), n: values.length }
}
const summary = Object.fromEntries([80, 0].map((delayMs) => {
  const selected = rows.filter((row) => row.delayMs === delayMs && row.request > 1)
  const previous = rows
  rows.length = rows.length
  const fields = ["totalMs", "externalMs", "localMs", "residualMs"]
  return [delayMs, Object.fromEntries(fields.map((field) => {
    const values = selected.map((row) => row[field])
    const sorted = [...values].sort((a, b) => a - b)
    const middle = Math.floor(sorted.length / 2)
    return [field, {
      medianMs: Number(((sorted[middle - 1] + sorted[middle]) / 2).toFixed(3)),
      minMs: Math.min(...values),
      maxMs: Math.max(...values),
      n: values.length,
    }]
  }))]
}))
console.log(JSON.stringify({ rows, summary }, null, 2))
'"'"

